export default function WorkspacePage() {
  const [location] = useLocation();
  const section = (location.split("?")[0]?.split("/").pop() ?? "warga");
  const requestedOrganizationId = new URLSearchParams(location.split("?")[1] ?? "").get("organization") ?? undefined;
  const configs: Record<string, { eyebrow: string; title: string; description: string }> = {
    warga: { eyebrow: "Direktori komunitas", title: "Data warga", description: "Kelola rumah tangga dan pastikan informasi lingkungan tetap rapi serta relevan." },
    tagihan: { eyebrow: "Keuangan lingkungan", title: "Tagihan", description: "Atur kategori iuran sesuai kebutuhan wilayah dan pantau verifikasi pembayaran." },
    acara: { eyebrow: "Agenda lingkungan", title: "Acara", description: "Susun kegiatan, pendaftaran kehadiran, dan pengingat dalam satu alur." },
    pengumuman: { eyebrow: "Informasi lingkungan", title: "Pengumuman", description: "Sampaikan kabar penting dengan arsip yang rapi dan akses berbasis wilayah." },
    donasi: { eyebrow: "Transparansi sosial", title: "Donasi", description: "Bangun kepercayaan melalui kampanye yang terukur dan pembaruan penggunaan dana." },
    forum: { eyebrow: "Ruang percakapan", title: "Forum warga", description: "Jaga diskusi tetap kontekstual, moderat, dan terhubung dengan kegiatan nyata." },
  };
  const config = configs[section] ?? configs.warga;
  const { data: memberships } = trpc.community.organizations.useQuery();
  const activeMembership = selectActiveMembership(memberships, requestedOrganizationId);
  const organizationId = activeMembership?.organization.id;
  const membershipRole = activeMembership?.membership.role;
  const canManageSection = section === "warga" || section === "acara" || section === "pengumuman" ? canManageHouseholdMembers(membershipRole) : section === "tagihan" ? ["platform_admin", "organization_admin", "rw_admin", "treasurer"].includes(membershipRole ?? "") : section === "donasi" ? canManageCampaigns(membershipRole as "platform_admin" | "organization_admin" | "rw_admin" | "rt_admin" | "treasurer" | "resident" | undefined) : section === "forum" ? ["platform_admin", "organization_admin", "rw_admin", "rt_admin"].includes(membershipRole ?? "") : false;

  return <div className="mx-auto max-w-[1360px] space-y-7 pb-8"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#9a6e2e]">{config.eyebrow} · RW 04 / RT 07</p><h1 className="mt-3 text-3xl font-semibold tracking-[-0.05em] text-[#183d34] sm:text-4xl">{config.title}</h1><p className="mt-2 max-w-[620px] text-sm leading-6 text-[#70857b]">{config.description}</p></div>{canManageSection && <Button className="h-10 rounded-xl bg-[#173b33] text-xs font-bold text-white hover:bg-[#255649]"><Plus className="mr-2 h-4 w-4" /> {section === "forum" ? "Mulai diskusi" : `Tambah ${section === "warga" ? "warga" : section}`}</Button>}</div>{section === "warga" && <ResidentsView organizationId={organizationId} canManageMembers={canManageHouseholdMembers(membershipRole)} />}{section === "tagihan" && <BillingView organizationId={organizationId} canReviewPayments={["platform_admin", "organization_admin", "rw_admin", "treasurer"].includes(membershipRole ?? "")} canManageBilling={["platform_admin", "organization_admin", "rw_admin", "treasurer"].includes(membershipRole ?? "")} />}{section === "acara" && <EventsView organizationId={organizationId} canManageEvents={canManageHouseholdMembers(membershipRole)} />}{section === "pengumuman" && <AnnouncementsView organizationId={organizationId} canManageAnnouncements={canManageHouseholdMembers(membershipRole)} />}{section === "donasi" && <DonationsView organizationId={organizationId} canReviewDonations={["platform_admin", "organization_admin", "rw_admin", "treasurer"].includes(membershipRole ?? "")} canManageCampaigns={canManageCampaigns(membershipRole as "platform_admin" | "organization_admin" | "rw_admin" | "rt_admin" | "treasurer" | "resident" | undefined)} />}{section === "forum" && <ForumView organizationId={organizationId} canCreateDiscussions={["platform_admin", "organization_admin", "rw_admin", "rt_admin"].includes(membershipRole ?? "")} />}</div>;
}

function ResidentsView({ organizationId, canManageMembers = false }: { organizationId?: string; canManageMembers?: boolean }) {
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(0);
  useEffect(() => { setPage(pageAfterResidentQueryChange()); }, [query]);
  const residentQuery = trpc.community.residents.useQuery({ organizationId: organizationId ?? "pending", query, limit: 20, offset: residentPageOffset(page) }, { enabled: Boolean(organizationId) });
  const filtered = residentQuery.data?.map(({ user, membership }) => ({ id: user.id, name: user.name ?? "Warga tanpa nama", home: "Detail alamat terbatas", status: membership.role === "resident" ? "Warga aktif" : membership.role, color: "bg-[#dceee3] text-[#34785e]" })) ?? [];
  return <><div className="grid gap-4 md:grid-cols-3"><MiniStat label="Warga ditemukan" value={residentQuery.data ? residentQuery.data.length.toLocaleString("id-ID") : "—"} note="Halaman aktif" icon={UsersRound} /><MiniStat label="Status data" value={residentQuery.isLoading ? "…" : residentQuery.isError ? "!" : "OK"} note={residentQuery.isError ? "Gagal memuat" : "Akses terkontrol"} icon={CheckCircle2} /><MiniStat label="Halaman" value={(page + 1).toString()} note="Navigasi direktori" icon={FileCheck2} /></div><Card className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="flex flex-col gap-4 border-b border-[#edf2ee] px-5 pb-4 pt-5 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Direktori warga</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Akses dibatasi berdasarkan wilayah dan peran.</p></div><div className="flex gap-2"><div className="relative flex-1 sm:w-64"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#9aaba2]" /><Input value={query} onChange={event => setQuery(event.target.value)} placeholder="Cari nama, email, atau alamat rumah tangga" className="h-9 rounded-xl border-[#dce8df] pl-9 text-xs" /></div></div></CardHeader><CardContent className="p-0"><div className="divide-y divide-[#edf2ee]">{residentQuery.isLoading ? <div className="p-6 text-sm text-[#8a9b92]">Memuat direktori warga...</div> : residentQuery.isError ? <div className="flex items-center justify-between gap-3 p-6 text-sm text-[#9b5c49]"><span>Direktori warga belum dapat dimuat.</span><Button variant="outline" onClick={() => residentQuery.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : filtered.length === 0 ? <div className="p-6 text-center"><p className="text-sm font-semibold text-[#35574c]">Belum ada warga yang cocok</p><p className="mt-1 text-xs text-[#8a9b92]">Coba ubah kata kunci atau tambahkan data warga ke wilayah aktif.</p></div> : filtered.map(person => <div key={person.id} className="flex items-center gap-3 px-5 py-4 sm:px-6"><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-sm font-bold ${person.color}`}>{person.name.split(" ").map(part => part[0]).join("").slice(0, 2)}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#35574c]">{person.name}</p><p className="mt-1 text-xs text-[#8a9b92]">{person.home} · {person.status}</p></div><Badge variant="outline" className="hidden rounded-full border-[#dbe8df] bg-[#f7fbf8] text-[10px] font-bold text-[#5c8171] sm:inline-flex">Aktif</Badge><Button variant="ghost" className="h-8 w-8 rounded-lg p-0 text-[#a2b0a8]"><ChevronRight className="h-4 w-4" /></Button></div>)}</div><div className="flex flex-col items-center gap-2 border-t border-[#edf2ee] px-5 py-3 sm:flex-row sm:justify-between sm:px-6"><span className="text-[11px] text-[#8a9b92]">Halaman {page + 1}</span><div className="flex gap-2"><Button variant="outline" disabled={page === 0} onClick={() => setPage(value => Math.max(0, value - 1))} className="h-8 rounded-lg border-[#dce8df] px-2 text-[11px] sm:px-3"><ChevronLeft className="h-4 w-4 sm:hidden" /><span className="hidden sm:inline">Sebelumnya</span></Button><Button variant="outline" disabled={!organizationId || filtered.length < 20} onClick={() => setPage(value => value + 1)} className="h-8 rounded-lg border-[#dce8df] px-2 text-[11px] sm:px-3"><span className="hidden sm:inline">Berikutnya</span><ChevronRight className="h-4 w-4 sm:hidden" /></Button></div></div></CardContent></Card><HouseholdMembersPanel organizationId={organizationId} canManageMembers={canManageMembers} /></>;
}

function HouseholdMembersPanel({ organizationId, canManageMembers = false }: { organizationId?: string; canManageMembers?: boolean }) {
  const [householdId, setHouseholdId] = useState("");
  const [userId, setUserId] = useState("");
  const [relationship, setRelationship] = useState("Anggota keluarga");
  const householdsQuery = trpc.households.list.useQuery({ organizationId: organizationId ?? "pending", limit: 50, offset: 0 }, { enabled: Boolean(organizationId) });
  const residentsQuery = trpc.community.residents.useQuery({ organizationId: organizationId ?? "pending", query: "", limit: 100, offset: 0 }, { enabled: Boolean(organizationId) });
  const membersQuery = trpc.households.listMembers.useQuery({ organizationId: organizationId ?? "pending", householdId }, { enabled: Boolean(organizationId && householdId) });
  const addMember = trpc.households.addMember.useMutation({ onSuccess: () => { membersQuery.refetch(); setUserId(householdMemberSuccessState().userId); toast.success("Anggota rumah tangga diperbarui"); }, onError: error => toast.error(error.message || "Anggota rumah tangga gagal diperbarui") });
  return <Card className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Keanggotaan rumah tangga</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">{canManageMembers ? "Tambahkan warga ke rumah tangga yang berada di wilayah aktif." : "Lihat anggota rumah tangga sesuai akses wilayah Anda."}</p></CardHeader><CardContent className="space-y-3 px-5 pb-5 sm:px-6 sm:pb-6"><div className="grid gap-2 sm:grid-cols-3"><select value={householdId} onChange={event => setHouseholdId(event.target.value)} className="h-9 rounded-lg border border-[#dce8df] bg-white px-3 text-xs text-[#5d7469]"><option value="">{householdsQuery.isLoading ? "Memuat rumah tangga..." : householdsQuery.isError ? "Rumah tangga gagal dimuat" : householdsQuery.data?.length ? "Pilih rumah tangga" : "Belum ada rumah tangga"}</option>{householdsQuery.data?.map(item => <option key={item.household.id} value={item.household.id}>{item.household.address} · {item.household.houseNumber ?? "tanpa nomor"}</option>)}</select>{canManageMembers && <><select value={userId} onChange={event => setUserId(event.target.value)} className="h-9 rounded-lg border border-[#dce8df] bg-white px-3 text-xs text-[#5d7469]"><option value="">{residentsQuery.isLoading ? "Memuat warga..." : residentsQuery.data?.length ? "Pilih warga" : "Belum ada warga"}</option>{residentsQuery.data?.map(item => <option key={item.user.id} value={item.user.id}>{item.user.name ?? item.user.email ?? `Warga ${item.user.id}`}</option>)}</select><Input value={relationship} onChange={event => setRelationship(event.target.value)} placeholder="Hubungan" className="h-9 rounded-lg border-[#dce8df] text-xs" /></>}</div>{canManageMembers && <Button onClick={() => organizationId && householdId && userId && addMember.mutate({ organizationId, householdId, userId: Number(userId), relationship, isHead: false })} disabled={!organizationId || !householdId || !userId || relationship.trim().length < 2 || addMember.isPending} className="h-9 rounded-lg bg-[#173b33] text-xs font-bold text-white">{addMember.isPending ? "Menyimpan..." : "Tambahkan anggota"}</Button>}{householdId && <div className="rounded-2xl border border-[#edf2ee] bg-[#f7fbf8] p-4">{membersQuery.isLoading ? <p className="text-xs text-[#8a9b92]">Memuat anggota...</p> : membersQuery.isError ? <div className="flex items-center justify-between gap-3"><p className="text-xs text-[#9b5c49]">Anggota belum dapat dimuat.</p><Button variant="outline" onClick={() => membersQuery.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : membersQuery.data?.length ? <div className="space-y-2">{membersQuery.data.map(item => <div key={item.member.userId} className="flex items-center justify-between text-xs"><span className="font-semibold text-[#35574c]">{item.user.name ?? item.user.email ?? `Warga ${item.user.id}`}</span><span className="text-[#8a9b92]">{item.member.relationship ?? "Anggota"}</span></div>)}</div> : <p className="text-xs text-[#8a9b92]">Belum ada anggota pada rumah tangga ini.</p>}</div>}</CardContent></Card>;
}

function BillingView({ organizationId, canReviewPayments = false, canManageBilling = false }: { organizationId?: string; canReviewPayments?: boolean; canManageBilling?: boolean }) {
  const [showUpload, setShowUpload] = useState(false);
  const [showCategoryForm, setShowCategoryForm] = useState(false);
  const [categoryName, setCategoryName] = useState("");
  const [categoryCode, setCategoryCode] = useState("");
  const [categoryAmount, setCategoryAmount] = useState("0");
  const [invoiceId, setInvoiceId] = useState("");
  const [proofFile, setProofFile] = useState<File | null>(null);
  const [paymentAmount, setPaymentAmount] = useState(""); const [periodTypeId, setPeriodTypeId] = useState(""); const [periodKey, setPeriodKey] = useState(""); const [dueAt, setDueAt] = useState(""); const [selectedPeriodId, setSelectedPeriodId] = useState("");
  const categories = trpc.billing.listTypes.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId) }); const periods = trpc.billing.listPeriods.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId) }); const myInvoices = trpc.billing.myInvoices.useQuery(undefined, { enabled: Boolean(organizationId) }); const myPaymentHistory = trpc.billing.myPaymentHistory.useQuery(undefined, { enabled: Boolean(organizationId) }); const pendingPayments = trpc.billing.listPending.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId && canReviewPayments) });
  const createCategory = trpc.billing.createType.useMutation({ onSuccess: () => { categories.refetch(); setShowCategoryForm(false); setCategoryName(""); setCategoryCode(""); setCategoryAmount("0"); } });
  const submitCategory = () => { if (!organizationId || !categoryName.trim() || !categoryCode.trim()) return; createCategory.mutate({ organizationId, name: categoryName.trim(), code: categoryCode.trim().toLowerCase().replace(/\\s+/g, "-"), defaultAmount: Number(categoryAmount) || 0, unit: "household" }); };
  const submitPayment = trpc.billing.submitPayment.useMutation({ onSuccess: () => { setShowUpload(false); setInvoiceId(""); setProofFile(null); setPaymentAmount(""); myPaymentHistory.refetch(); myInvoices.refetch(); toast.success("Bukti pembayaran dikirim"); }, onError: error => toast.error(error.message || "Bukti pembayaran gagal dikirim") }); const verifyPayment = trpc.billing.verifyPayment.useMutation({ onSuccess: () => { pendingPayments.refetch(); toast.success("Status pembayaran diperbarui"); }, onError: error => toast.error(error.message || "Status pembayaran gagal diperbarui") }); const createPeriod = trpc.billing.createPeriod.useMutation({ onSuccess: () => { periods.refetch(); setPeriodKey(""); setDueAt(""); } }); const issueInvoices = trpc.billing.issueInvoices.useMutation({ onSuccess: result => { periods.refetch(); toast.success(`${result.count} invoice berhasil diterbitkan`); }, onError: error => toast.error(error.message || "Invoice gagal diterbitkan") }); const createPeriodNow = () => { if (!organizationId || !periodTypeId || !periodKey || !dueAt) return; createPeriod.mutate({ organizationId, billingTypeId: periodTypeId, periodKey, dueAt: new Date(dueAt).getTime() }); };
  const submitProof = async () => { if (!invoiceId.trim() || !proofFile || !paymentAmount || proofFile.size > 5 * 1024 * 1024) return; const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1] ?? ""; submitPayment.mutate({ invoiceId: invoiceId.trim(), amount: Number(paymentAmount), filename: proofFile.name, mimeType: proofFile.type as "image/jpeg" | "image/png" | "application/pdf", contentBase64: base64 }); }; reader.readAsDataURL(proofFile); };
  const visibleInvoices = categories.data?.map(category => ({ title: category.name, period: "Kategori aktif", amount: `Rp ${category.defaultAmount.toLocaleString("id-ID")}`, status: category.active ? "Aktif" : "Nonaktif", tone: "green" })) ?? [];
  return <><div className="grid gap-4 md:grid-cols-3"><MiniStat label="Kategori tagihan" value={categories.data ? categories.data.length.toLocaleString("id-ID") : "—"} note="Wilayah aktif" icon={FileText} /><MiniStat label="Periode tagihan" value={periods.data ? periods.data.length.toLocaleString("id-ID") : "—"} note="Tersedia untuk penerbitan" icon={ShieldCheck} /><MiniStat label="Menunggu review" value={pendingPayments.data ? pendingPayments.data.length.toLocaleString("id-ID") : "—"} note={canReviewPayments ? "Pembayaran masuk" : "Akses bendahara diperlukan"} icon={WalletCards} /></div><div className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]"><Card className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="flex flex-row items-center justify-between space-y-0 px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><div><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Tagihan periode Mei</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Kategori dapat ditambahkan sesuai kebutuhan wilayah.</p></div>{canManageBilling && <Button onClick={() => setShowCategoryForm(value => !value)} variant="outline" className="h-9 rounded-xl border-[#dce8df] text-xs font-bold text-[#4e7465]"><Plus className="mr-1.5 h-3.5 w-3.5" /> Kategori</Button>}</CardHeader>{canManageBilling && showCategoryForm && <div className="mx-5 mb-3 rounded-2xl border border-[#dce8df] bg-[#f7fbf8] p-4 sm:mx-6"><div className="flex items-center justify-between"><p className="text-xs font-bold text-[#35574c]">Kategori iuran baru</p><button onClick={() => setShowCategoryForm(false)} className="text-[#9aaba2]" aria-label="Tutup form"><X className="h-4 w-4" /></button></div><div className="mt-3 grid gap-2 sm:grid-cols-3"><Input value={categoryName} onChange={event => setCategoryName(event.target.value)} placeholder="Nama kategori" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Input value={categoryCode} onChange={event => setCategoryCode(event.target.value)} placeholder="kode-kategori" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Input value={categoryAmount} onChange={event => setCategoryAmount(event.target.value)} type="number" min="0" placeholder="Nominal" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /></div><Button onClick={submitCategory} disabled={!organizationId || createCategory.isPending} className="mt-3 h-9 rounded-lg bg-[#173b33] text-xs font-bold text-white">{createCategory.isPending ? "Menyimpan..." : "Simpan kategori"}</Button></div>}{canManageBilling && <div className="mx-5 mb-3 grid gap-2 rounded-2xl border border-[#dce8df] bg-[#f7fbf8] p-4 sm:mx-6 sm:grid-cols-4"><div className="flex items-center gap-2"><select value={periodTypeId} onChange={event => setPeriodTypeId(event.target.value)} className="h-9 min-w-0 flex-1 rounded-lg border border-[#dce8df] bg-white px-3 text-xs text-[#5d7469]"><option value="">{categories.isLoading ? "Memuat kategori..." : categories.isError ? "Kategori gagal dimuat" : categories.data?.length ? "Pilih kategori" : "Belum ada kategori aktif"}</option>{categories.data?.filter(category => category.active).map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select>{categories.isError && <Button type="button" variant="outline" onClick={() => categories.refetch()} className="h-9 shrink-0 rounded-lg border-[#f0d7cf] px-2 text-[10px] font-bold text-[#9b5c49]">Coba lagi</Button>}</div><Input value={periodKey} onChange={event => setPeriodKey(event.target.value)} placeholder="Periode YYYY-MM" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Input value={dueAt} onChange={event => setDueAt(event.target.value)} type="datetime-local" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Button onClick={createPeriodNow} disabled={!organizationId || !periodTypeId || !periodKey || !dueAt || createPeriod.isPending} className="h-9 rounded-lg bg-[#173b33] text-xs font-bold text-white">{createPeriod.isPending ? "Menyimpan..." : "Buat periode"}</Button></div>}{canManageBilling && <div className="mx-5 mb-3 grid gap-2 rounded-2xl border border-[#dce8df] bg-white p-4 sm:mx-6 sm:grid-cols-[1fr_auto]"><div className="flex items-center gap-2"><select value={selectedPeriodId} onChange={event => setSelectedPeriodId(event.target.value)} className="h-9 min-w-0 flex-1 rounded-lg border border-[#dce8df] bg-white px-3 text-xs text-[#5d7469]"><option value="">{periods.isLoading ? "Memuat periode..." : periods.isError ? "Periode gagal dimuat" : periods.data?.length ? "Pilih periode untuk menerbitkan invoice" : "Belum ada periode tagihan"}</option>{periods.data?.map(item => <option key={item.period.id} value={item.period.id}>{item.type.name} · {item.period.periodKey} · {item.period.status}</option>)}</select>{periods.isError && <Button type="button" variant="outline" onClick={() => periods.refetch()} className="h-9 shrink-0 rounded-lg border-[#f0d7cf] px-2 text-[10px] font-bold text-[#9b5c49]">Coba lagi</Button>}</div><Button onClick={() => organizationId && selectedPeriodId && issueInvoices.mutate({ organizationId, billingPeriodId: selectedPeriodId })} disabled={!organizationId || !selectedPeriodId || issueInvoices.isPending} className="h-9 rounded-lg bg-[#b47b2c] text-xs font-bold text-white">{issueInvoices.isPending ? "Menerbitkan..." : "Terbitkan invoice"}</Button></div>}<CardContent className="space-y-3 px-5 pb-5 sm:px-6 sm:pb-6">{visibleInvoices.length ? visibleInvoices.map(invoice => <div key={invoice.title} className="flex flex-col gap-3 rounded-2xl border border-[#e7eee9] p-4 sm:flex-row sm:items-center"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${invoice.tone === "green" ? "bg-[#e8f3ec] text-[#398065]" : invoice.tone === "gold" ? "bg-[#fbf0dc] text-[#a87027]" : "bg-[#e9eef8] text-[#456da8]"}`}><WalletCards className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#35574c]">{invoice.title}</p><p className="mt-1 text-xs text-[#8a9b92]">{invoice.period} · {invoice.amount}</p></div><Badge className={`w-fit rounded-full px-2.5 py-1 text-[10px] font-bold ${invoice.tone === "green" ? "bg-[#e7f3eb] text-[#438367] hover:bg-[#e7f3eb]" : invoice.tone === "gold" ? "bg-[#fbf0dc] text-[#a87027] hover:bg-[#fbf0dc]" : "bg-[#e9eef8] text-[#456da8] hover:bg-[#e9eef8]"}`}>{invoice.status}</Badge></div>) : <div className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-5 text-center text-sm text-[#8a9b92]">Belum ada kategori tagihan di wilayah ini.</div>}</CardContent></Card><Card className="rounded-[24px] border-[#e0e9e2] bg-[#eef5ef] shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#9a6e2e]">Alur warga</p><CardTitle className="mt-2 text-xl tracking-[-0.04em] text-[#23483d]">Kirim bukti bayar</CardTitle></CardHeader><CardContent className="px-5 pb-5 sm:px-6 sm:pb-6"><p className="text-sm leading-6 text-[#71877c]">Bukti pembayaran tersimpan privat dan baru terlihat oleh bendahara yang berwenang.</p>{showUpload ? <div className="mt-5 space-y-3"><div className="flex items-center gap-2"><select value={invoiceId} onChange={event => { const value = event.target.value; setInvoiceId(value); const invoice = myInvoices.data?.find(item => item.id === value); setPaymentAmount(invoice ? String(invoice.amount) : ""); }} className="h-10 min-w-0 flex-1 rounded-xl border border-[#d2e2d7] bg-white px-3 text-xs text-[#5d7469]"><option value="">{myInvoices.isLoading ? "Memuat tagihan..." : myInvoices.isError ? "Tagihan gagal dimuat" : myInvoices.data?.length ? "Pilih tagihan Anda" : "Belum ada tagihan unpaid"}</option>{myInvoices.data?.map(invoice => <option key={invoice.id} value={invoice.id}>{invoice.typeName} · {invoice.periodKey} · Rp {invoice.amount.toLocaleString("id-ID")}</option>)}</select>{myInvoices.isError && <Button type="button" variant="outline" onClick={() => myInvoices.refetch()} className="h-10 shrink-0 rounded-xl border-[#f0d7cf] px-2 text-[10px] font-bold text-[#9b5c49]">Coba lagi</Button>}</div><Input value={paymentAmount} onChange={event => setPaymentAmount(event.target.value)} type="number" min="1" placeholder="Nominal bayar" className="h-10 rounded-xl border-[#d2e2d7] bg-white text-xs" /><Input type="file" accept="image/jpeg,image/png,application/pdf" onChange={event => setProofFile(event.target.files?.[0] ?? null)} className="h-10 rounded-xl border-[#d2e2d7] bg-white text-xs" /><div className="rounded-xl border border-dashed border-[#b8d3c1] bg-white p-5 text-center"><UploadCloud className="mx-auto h-6 w-6 text-[#4b9273]" /><p className="mt-2 text-xs font-semibold text-[#456b5b]">Bukti akan diunggah privat</p><p className="mt-1 text-[10px] text-[#91a399]">JPG, PNG, atau PDF · Maks. 5 MB</p></div><Button onClick={submitProof} disabled={!invoiceId.trim() || !paymentAmount || !proofFile || proofFile.size > 5 * 1024 * 1024 || submitPayment.isPending} className="h-10 w-full rounded-xl bg-[#173b33] text-xs font-bold text-white">{submitPayment.isPending ? "Mengunggah..." : "Kirim untuk diverifikasi"}</Button></div> : <Button onClick={() => setShowUpload(true)} className="mt-5 h-10 rounded-xl bg-[#173b33] px-4 text-xs font-bold text-white hover:bg-[#255649]"><UploadCloud className="mr-2 h-4 w-4" /> Unggah bukti pembayaran</Button>}<div className="mt-5 rounded-2xl border border-[#dce8df] bg-white/70 p-4"><p className="text-xs font-bold text-[#35574c]">Riwayat pengajuan</p>{myPaymentHistory.isLoading ? <p className="mt-2 text-[11px] text-[#8a9b92]">Memuat riwayat...</p> : myPaymentHistory.isError ? <div className="mt-2 flex items-center justify-between gap-2"><p className="text-[11px] text-[#9b5c49]">Riwayat belum dapat dimuat.</p><Button variant="outline" onClick={() => myPaymentHistory.refetch()} className="h-7 rounded-lg border-[#f0d7cf] px-2 text-[10px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : myPaymentHistory.data?.length ? <div className="mt-2 space-y-2">{myPaymentHistory.data.slice(0, 5).map(item => <div key={item.history.id} className="flex items-center justify-between gap-2 text-[11px]"><span className="truncate text-[#71877c]">{item.typeName} · {item.periodKey}</span><span className="font-bold capitalize text-[#4e7465]">{item.history.status}</span></div>)}</div> : <p className="mt-2 text-[11px] text-[#8a9b92]">Belum ada pengajuan pembayaran.</p>}</div></CardContent></Card></div>{canReviewPayments && <Card className="mt-5 rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Review pembayaran</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Hanya bendahara dan pengurus berwenang yang dapat mengubah status.</p></CardHeader><CardContent className="space-y-3 px-5 pb-5 sm:px-6 sm:pb-6">{pendingPayments.isLoading ? <div className="rounded-2xl bg-[#f7fbf8] p-5 text-sm text-[#8a9b92]">Memuat pembayaran pending...</div> : pendingPayments.isError ? <div className="flex items-center justify-between gap-3 rounded-2xl bg-[#fff8f5] p-5 text-sm text-[#9b5c49]"><span>Pembayaran belum dapat dimuat.</span><Button variant="outline" onClick={() => pendingPayments.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : pendingPayments.data?.length ? pendingPayments.data.map(({ payment, invoice, household, history }) => <div key={payment.id} className="flex flex-col gap-3 rounded-2xl border border-[#e7eee9] p-4 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#35574c]">Invoice {invoice.id}</p><p className="mt-1 text-xs text-[#8a9b92]">Rumah tangga {household.id} · Rp {payment.amount.toLocaleString("id-ID")}</p>{history.length > 0 && <p className="mt-2 text-[10px] text-[#789084]">Riwayat: {history.map(item => `${item.status} · ${new Date(item.createdAt).toLocaleString("id-ID")}`).join("  |  ")}</p>}</div><div className="flex gap-2"><Button onClick={() => organizationId && verifyPayment.mutate({ organizationId, paymentId: payment.id, status: "rejected" })} disabled={verifyPayment.isPending} variant="outline" className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[10px] font-bold text-[#9b5c49]">Tolak</Button><Button onClick={() => organizationId && verifyPayment.mutate({ organizationId, paymentId: payment.id, status: "verified" })} disabled={verifyPayment.isPending} className="h-8 rounded-lg bg-[#173b33] px-3 text-[10px] font-bold text-white">Verifikasi</Button></div></div>) : <div className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-5 text-center text-sm text-[#8a9b92]">Tidak ada pembayaran yang menunggu review.</div>}</CardContent></Card>}</>;
}

function EventsView({ organizationId, canManageEvents = false }: { organizationId?: string; canManageEvents?: boolean }) { const [page, setPage] = useState(0); const [showForm, setShowForm] = useState(false); const [title, setTitle] = useState(""); const [location, setLocation] = useState(""); const [startsAt, setStartsAt] = useState(""); const [reminderEventId, setReminderEventId] = useState(""); const [reminderTemplate, setReminderTemplate] = useState("event_reminder"); const [reminderMinutes, setReminderMinutes] = useState("1440"); const eventQuery = trpc.events.list.useQuery({ organizationId: organizationId ?? "pending", limit: 20, offset: page * 20 }, { enabled: Boolean(organizationId) }); const addReminderRule = trpc.events.addReminderRule.useMutation({ onSuccess: () => toast.success("Pengingat WhatsApp dijadwalkan"), onError: error => toast.error(error.message || "Pengingat gagal dijadwalkan") }); const createEvent = trpc.events.create.useMutation({ onSuccess: () => { eventQuery.refetch(); setShowForm(false); setTitle(""); setLocation(""); setStartsAt(""); toast.success("Acara tersimpan sebagai draft"); }, onError: error => toast.error(error.message || "Acara gagal disimpan") }); const publishEvent = trpc.events.publish.useMutation({ onSuccess: () => { eventQuery.refetch(); toast.success("Acara diterbitkan"); }, onError: error => toast.error(error.message || "Acara gagal diterbitkan") }); const register = trpc.events.register.useMutation({ onSuccess: () => { eventQuery.refetch(); toast.success("Kehadiran berhasil dicatat"); }, onError: error => toast.error(error.message || "Pendaftaran gagal") }); const createEventNow = () => { if (!organizationId || !title.trim() || !startsAt) return; createEvent.mutate({ organizationId, title: title.trim(), slug: title.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""), location: location.trim() || undefined, startsAt: new Date(startsAt).getTime() }); }; const visibleEvents = eventQuery.data?.map(({ event, attendeeCount }) => ({ id: event.id, title: event.title, eventDate: event.startsAt, date: new Date(event.startsAt).toLocaleString("id-ID", { dateStyle: "full", timeStyle: "short" }), location: event.location ?? "Lokasi menyusul", attendees: attendeeCount, capacity: event.capacity, status: event.status === "published" ? "Terpublikasi" : "Draft" })) ?? []; return <><div className="grid gap-4 md:grid-cols-3"><MiniStat label="Acara tercatat" value={eventQuery.data ? eventQuery.data.length.toLocaleString("id-ID") : "—"} note="Wilayah aktif" icon={CalendarDays} /><MiniStat label="Total pendaftar" value={eventQuery.data ? eventQuery.data.reduce((sum, item) => sum + Number(item.attendeeCount ?? 0), 0).toLocaleString("id-ID") : "—"} note="Dari agenda yang tersedia" icon={UsersRound} /><MiniStat label="Pengingat" value={eventQuery.isLoading ? "…" : eventQuery.isError ? "!" : "Manual"} note={eventQuery.isError ? "Gagal memuat agenda" : "Atur per acara"} icon={MessageCircle} /></div><Card className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="flex flex-row items-center justify-between space-y-0 px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><div><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Agenda kegiatan</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Pengingat memakai template WhatsApp yang disetujui.</p></div>{canManageEvents && <Button onClick={() => setShowForm(value => !value)} variant="outline" className="h-9 rounded-xl border-[#dce8df] text-xs font-bold text-[#4e7465]"><Plus className="mr-1.5 h-3.5 w-3.5" /> Acara baru</Button>}</CardHeader>{canManageEvents && <div className="mx-5 mb-3 grid gap-2 rounded-2xl border border-[#ecd9b4] bg-[#fffaf0] p-4 sm:mx-6 sm:grid-cols-4"><select value={reminderEventId} onChange={event => setReminderEventId(event.target.value)} className="h-9 rounded-lg border border-[#ead9b7] bg-white px-3 text-xs text-[#6d624b]"><option value="">{eventQuery.isLoading ? "Memuat acara..." : eventQuery.isError ? "Acara gagal dimuat" : visibleEvents.length ? "Pilih acara untuk reminder" : "Belum ada acara"}</option>{visibleEvents.map(event => <option key={event.id} value={event.id}>{event.title}</option>)}</select><Input value={reminderTemplate} onChange={event => setReminderTemplate(event.target.value)} placeholder="Template WhatsApp" className="h-9 rounded-lg border-[#ead9b4] bg-white text-xs" /><select value={reminderMinutes} onChange={event => setReminderMinutes(event.target.value)} className="h-9 rounded-lg border border-[#ead9b7] bg-white px-3 text-xs text-[#6d624b]"><option value="60">1 jam sebelum</option><option value="1440">24 jam sebelum</option><option value="2880">48 jam sebelum</option></select><Button onClick={() => organizationId && reminderEventId && addReminderRule.mutate({ organizationId, eventId: reminderEventId, templateName: reminderTemplate.trim(), minutesBefore: Number(reminderMinutes) })} disabled={!organizationId || !reminderEventId || !/^[a-z0-9_]+$/i.test(reminderTemplate.trim()) || addReminderRule.isPending} className="h-9 rounded-lg bg-[#b47b2c] text-xs font-bold text-white">{addReminderRule.isPending ? "Menjadwalkan..." : "Jadwalkan reminder"}</Button></div>}{canManageEvents && showForm && <div className="mx-5 mb-3 grid gap-2 rounded-2xl border border-[#dce8df] bg-[#f7fbf8] p-4 sm:mx-6 sm:grid-cols-3"><Input value={title} onChange={event => setTitle(event.target.value)} placeholder="Nama acara" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Input value={location} onChange={event => setLocation(event.target.value)} placeholder="Lokasi" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Input value={startsAt} onChange={event => setStartsAt(event.target.value)} type="datetime-local" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Button onClick={createEventNow} disabled={!organizationId || !title.trim() || !startsAt || createEvent.isPending} className="h-9 rounded-lg bg-[#173b33] text-xs font-bold text-white sm:col-span-3">{createEvent.isPending ? "Menyimpan..." : "Simpan acara"}</Button></div>}<CardContent className="space-y-3 px-5 pb-5 sm:px-6 sm:pb-6">{eventQuery.isLoading ? <div className="rounded-2xl border border-[#e0e9e2] bg-[#f7fbf8] p-6 text-sm text-[#8a9b92]">Memuat agenda...</div> : eventQuery.isError ? <div className="flex items-center justify-between gap-3 rounded-2xl border border-[#f0d7cf] bg-[#fff8f5] p-6 text-sm text-[#9b5c49]"><span>Agenda belum dapat dimuat.</span><Button variant="outline" onClick={() => eventQuery.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : visibleEvents.length === 0 ? <div className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-6 text-center"><p className="text-sm font-semibold text-[#35574c]">Belum ada acara</p><p className="mt-1 text-xs text-[#8a9b92]">Buat agenda pertama untuk warga di wilayah aktif.</p></div> : visibleEvents.map(event => <div key={event.title} className="flex flex-col gap-4 rounded-2xl border border-[#e7eee9] p-4 sm:flex-row sm:items-center"><div className="flex h-12 w-12 shrink-0 flex-col items-center justify-center rounded-xl bg-[#e8f3ec] text-[#34785e]"><span className="text-[9px] font-bold uppercase">{new Date(event.eventDate).toLocaleDateString("id-ID", { month: "short" })}</span><span className="text-lg font-bold">{new Date(event.eventDate).getDate()}</span></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#35574c]">{event.title}</p><p className="mt-1 text-xs text-[#8a9b92]">{event.date} · {event.location}</p><p className="mt-2 text-[11px] font-semibold text-[#5c8171]">{event.attendees} warga terdaftar</p></div><div className="flex items-center gap-2"><Badge variant="outline" className="w-fit rounded-full border-[#dbe8df] bg-[#f7fbf8] text-[10px] font-bold text-[#5c8171]">{event.status}</Badge>{event.status === "Draft" && organizationId && <Button onClick={() => publishEvent.mutate({ organizationId, eventId: event.id })} disabled={publishEvent.isPending} variant="outline" className="h-8 rounded-lg border-[#dce8df] px-3 text-[10px] font-bold text-[#4e7465]">Terbitkan</Button>}{event.id && <><Button onClick={() => register.mutate({ eventId: event.id })} disabled={register.isPending || (event.capacity !== null && event.capacity !== undefined && Number(event.attendees) >= event.capacity)} variant="outline" className="h-8 rounded-lg border-[#dce8df] px-3 text-[10px] font-bold text-[#4e7465]">{event.capacity !== null && event.capacity !== undefined && Number(event.attendees) >= event.capacity ? "Penuh" : "Daftar hadir"}</Button><Button onClick={() => organizationId && addReminderRule.mutate({ organizationId, eventId: reminderEventId || event.id, templateName: reminderTemplate.trim(), minutesBefore: Number(reminderMinutes) })} disabled={addReminderRule.isPending || !reminderTemplate.trim() || Number(reminderMinutes) < 60 || Number(reminderMinutes) > 43200} variant="outline" className="h-8 rounded-lg border-[#ecd9b4] px-3 text-[10px] font-bold text-[#9a6e2e]">Atur reminder</Button></>}</div></div>)}</CardContent></Card><div className="flex flex-col items-center gap-2 pt-1 sm:flex-row sm:justify-between"><span className="text-[11px] text-[#8a9b92]">Halaman {page + 1}</span><div className="flex gap-2"><Button variant="outline" disabled={page === 0} onClick={() => setPage(value => Math.max(0, value - 1))} className="h-8 rounded-lg border-[#dce8df] px-2 text-[11px] sm:px-3"><ChevronLeft className="h-4 w-4 sm:hidden" /><span className="hidden sm:inline">Sebelumnya</span></Button><Button variant="outline" disabled={!organizationId || visibleEvents.length < 20} onClick={() => setPage(value => value + 1)} className="h-8 rounded-lg border-[#dce8df] px-2 text-[11px] sm:px-3"><span className="hidden sm:inline">Berikutnya</span><ChevronRight className="h-4 w-4 sm:hidden" /></Button></div></div></>; }

function AnnouncementCommentSection({ organizationId, announcementId }: { organizationId: string; announcementId: string }) { const [commentBody, setCommentBody] = useState(""); const topicMutation = trpc.forum.findOrCreateTopic.useMutation(); const [topicId, setTopicId] = useState<string | null>(null); const postsQuery = trpc.forum.listPosts.useQuery({ topicId: topicId ?? "pending" }, { enabled: Boolean(topicId) }); const createPost = trpc.forum.createPost.useMutation({ onSuccess: () => { setCommentBody(""); postsQuery.refetch(); toast.success("Komentar terkirim"); }, onError: error => toast.error(error.message || "Gagal mengirim komentar") }); const handleExpand = () => { if (!topicId && !topicMutation.isPending) { topicMutation.mutate({ organizationId, scopeType: "announcement", scopeId: announcementId }, { onSuccess: topic => { if (topic) setTopicId(topic.id); } }); } }; const submitComment = () => { if (!topicId || !commentBody.trim()) return; createPost.mutate({ topicId, body: commentBody.trim() }); }; const posts = postsQuery.data ?? []; return <div className="mt-4 border-t border-[#edf2ee] pt-4"><button onClick={handleExpand} className="flex items-center gap-2 text-[11px] font-bold text-[#4b8068] hover:text-[#2d6049]"><MessageCircle className="h-3.5 w-3.5" /> Komentar ({posts.length})</button>{topicId && <div className="mt-3 space-y-3"><div className="max-h-60 space-y-2 overflow-y-auto"><div className="flex gap-2"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#dceee3] text-[9px] font-bold text-[#34785e]">AR</div><div className="min-w-0 flex-1"><Textarea value={commentBody} onChange={event => setCommentBody(event.target.value)} placeholder="Tulis komentar..." className="min-h-16 resize-none rounded-xl border-[#dce8df] text-xs" /><div className="mt-1 flex justify-end"><Button onClick={submitComment} disabled={!commentBody.trim() || createPost.isPending} className="h-7 rounded-lg bg-[#173b33] px-3 text-[10px] font-bold text-white">{createPost.isPending ? "Mengirim..." : "Kirim"}</Button></div></div></div>{posts.map(({ post, author }) => <div key={post.id} className="flex gap-2"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#e9eef8] text-[9px] font-bold text-[#456da8]">{(author.name ?? "U").split(" ").map(part => part[0]).join("").slice(0, 2)}</div><div className="min-w-0 flex-1 rounded-xl border border-[#edf2ee] bg-[#f7fbf8] px-3 py-2"><p className="text-[10px] font-bold text-[#35574c]">{author.name ?? "Warga"}</p><p className="mt-0.5 text-xs leading-5 text-[#6d8278]">{post.body}</p></div></div>)}{postsQuery.isLoading && <p className="text-[10px] text-[#8a9b92]">Memuat komentar...</p>}</div></div>}</div>; }
function AnnouncementsView({ organizationId, canManageAnnouncements = false }: { organizationId?: string; canManageAnnouncements?: boolean }) { const [page, setPage] = useState(0); const [title, setTitle] = useState(""); const [body, setBody] = useState(""); const announcements = trpc.announcements.list.useQuery({ organizationId: organizationId ?? "pending", limit: 20, offset: page * 20 }, { enabled: Boolean(organizationId) }); const create = trpc.announcements.create.useMutation({ onSuccess: () => { announcements.refetch(); setTitle(""); setBody(""); toast.success("Draft pengumuman tersimpan"); }, onError: error => toast.error(error.message || "Draft gagal disimpan") }); const publishAnnouncement = trpc.announcements.publish.useMutation({ onSuccess: () => { announcements.refetch(); toast.success("Pengumuman diterbitkan"); }, onError: error => toast.error(error.message || "Pengumuman gagal diterbitkan") }); const publish = () => { if (!organizationId || !title.trim() || !body.trim()) return; create.mutate({ organizationId, title: title.trim(), body: body.trim(), slug: title.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") }); }; const items = announcements.data ?? []; return <div className="grid gap-5 xl:grid-cols-[1fr_0.45fr]"><div className="space-y-4">{canManageAnnouncements && <Card className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Tulis pengumuman</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Draft baru tersimpan di wilayah aktif.</p></CardHeader><CardContent className="space-y-2 px-5 pb-5 sm:px-6 sm:pb-6"><Input value={title} onChange={event => setTitle(event.target.value)} placeholder="Judul pengumuman" className="h-10 rounded-xl border-[#dce8df]" /><Textarea value={body} onChange={event => setBody(event.target.value)} placeholder="Isi informasi untuk warga..." className="min-h-28 rounded-xl border-[#dce8df]" /><Button onClick={publish} disabled={!organizationId || !title.trim() || !body.trim() || create.isPending} className="h-10 rounded-xl bg-[#173b33] text-xs font-bold text-white">{create.isPending ? "Menyimpan..." : "Simpan draft"}</Button></CardContent></Card>}{items.length ? items.map(item => <Card key={item.id} className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardContent className="p-5 sm:p-6"><div className="flex items-start gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#fbefd9] text-[#a87027]"><Megaphone className="h-4 w-4" /></div><div className="min-w-0 flex-1"><h3 className="text-sm font-semibold text-[#35574c]">{item.title}</h3><p className="mt-2 whitespace-pre-wrap text-xs leading-5 text-[#6d8278]">{item.body}</p><p className="mt-3 text-[10px] font-bold uppercase tracking-[0.12em] text-[#8ea097]">{item.status === "published" ? `Terbit ${item.publishedAt ? new Date(item.publishedAt).toLocaleDateString("id-ID") : ""}` : "Draft"}</p>{canManageAnnouncements && item.status === "draft" && <Button onClick={() => organizationId && publishAnnouncement.mutate({ organizationId, announcementId: item.id })} disabled={publishAnnouncement.isPending} variant="outline" className="mt-3 h-8 rounded-lg border-[#dce8df] text-[10px] font-bold text-[#4e7465]">Terbitkan</Button>}</div></div>{item.status === "published" && organizationId && <AnnouncementCommentSection organizationId={organizationId} announcementId={item.id} />}</CardContent></Card>) : announcements.isLoading ? <div className="rounded-2xl border border-[#e0e9e2] bg-white p-6 text-sm text-[#8a9b92]">Memuat pengumuman...</div> : announcements.isError ? <div className="flex items-center justify-between gap-3 rounded-2xl border border-[#f0d7cf] bg-[#fff8f5] p-6 text-sm text-[#9b5c49]"><span>Pengumuman belum dapat dimuat.</span><Button variant="outline" onClick={() => announcements.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : <div className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-6 text-center"><p className="text-sm font-semibold text-[#35574c]">Belum ada pengumuman</p><p className="mt-1 text-xs text-[#8a9b92]">Simpan draft pertama untuk mulai membangun arsip informasi warga.</p></div>}</div><div className="flex flex-col items-center gap-2 sm:flex-row sm:justify-between"><span className="text-[11px] text-[#8a9b92]">Halaman {page + 1}</span><div className="flex gap-2"><Button variant="outline" disabled={page === 0} onClick={() => setPage(value => Math.max(0, value - 1))} className="h-8 rounded-lg border-[#dce8df] px-2 text-[11px] sm:px-3"><ChevronLeft className="h-4 w-4 sm:hidden" /><span className="hidden sm:inline">Sebelumnya</span></Button><Button variant="outline" disabled={!organizationId || items.length < 20} onClick={() => setPage(value => value + 1)} className="h-8 rounded-lg border-[#dce8df] px-2 text-[11px] sm:px-3"><span className="hidden sm:inline">Berikutnya</span><ChevronRight className="h-4 w-4 sm:hidden" /></Button></div></div><Card className="h-fit rounded-[24px] border-[#e0e9e2] bg-[#173b33] text-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#9ec1b2]">Prinsip komunikasi</p><CardTitle className="mt-2 text-xl tracking-[-0.04em] text-white">Jelas dan mudah dicari</CardTitle></CardHeader><CardContent className="px-5 pb-5 sm:px-6 sm:pb-6"><p className="text-sm leading-6 text-[#c1d8cb]">Gunakan judul spesifik, tanggal, dan tindakan yang perlu dilakukan warga.</p></CardContent></Card></div>; }

function DonationsView({ organizationId, canReviewDonations = false, canManageCampaigns = false }: { organizationId?: string; canReviewDonations?: boolean; canManageCampaigns?: boolean }) { const [amount, setAmount] = useState(""); const [campaignTitle, setCampaignTitle] = useState(""); const [campaignSlug, setCampaignSlug] = useState(""); const [campaignDescription, setCampaignDescription] = useState(""); const [campaignTarget, setCampaignTarget] = useState(""); const [createdCampaign, setCreatedCampaign] = useState<{ id: string; title: string; status: string } | null>(null); const [selectedCampaign, setSelectedCampaign] = useState(""); const [usageCampaign, setUsageCampaign] = useState(""); const [usageAmount, setUsageAmount] = useState(""); const [usageDescription, setUsageDescription] = useState(""); const [usageEvidenceFileId, setUsageEvidenceFileId] = useState(""); const [reviewCampaignId, setReviewCampaignId] = useState<string | null>(null); const campaignQuery = trpc.campaigns.list.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId) }); const draftQuery = trpc.campaigns.drafts.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId && canReviewDonations) }); const pendingQuery = trpc.campaigns.pending.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId && canReviewDonations) }); const verifyDonation = trpc.campaigns.verifyDonation.useMutation({ onSuccess: () => { for (const target of campaignReviewRefreshTargets()) { if (target === "pending") pendingQuery.refetch(); else campaignQuery.refetch(); } toast.success("Status kontribusi diperbarui"); }, onError: error => toast.error(error.message || "Status kontribusi gagal diperbarui") }); const contribute = trpc.campaigns.contribute.useMutation({ onSuccess: () => { setAmount(""); setSelectedCampaign(""); campaignQuery.refetch(); toast.success("Kontribusi tercatat untuk verifikasi"); }, onError: error => toast.error(error.message || "Kontribusi gagal dicatat") }); const filesQuery = trpc.files.listOwned.useQuery(undefined, { enabled: Boolean(organizationId) }); const uploadEvidence = trpc.files.uploadCampaignEvidence.useMutation({ onSuccess: file => { filesQuery.refetch(); setUsageEvidenceFileId(file.id); toast.success("Bukti private berhasil diunggah"); }, onError: error => toast.error(error.message || "Unggah bukti gagal") }); const chooseEvidence = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file || !organizationId) return; const reader = new FileReader(); reader.onload = () => { const contentBase64 = String(reader.result).split(",")[1] ?? ""; uploadEvidence.mutate({ organizationId, filename: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "application/pdf", contentBase64 }); }; reader.readAsDataURL(file); }; const addFundUsage = trpc.campaigns.addFundUsage.useMutation({ onSuccess: () => { setUsageCampaign(""); setUsageAmount(""); setUsageDescription(""); setUsageEvidenceFileId(""); toast.success("Penggunaan dana tersimpan"); }, onError: error => toast.error(error.message || "Penggunaan dana gagal disimpan") }); const saveUsage = () => { if (!organizationId || !usageCampaign || !usageAmount || !usageDescription.trim()) return; addFundUsage.mutate({ organizationId, campaignId: usageCampaign, amount: Number(usageAmount), description: usageDescription.trim(), evidenceFileId: usageEvidenceFileId || undefined }); }; const visibleCampaigns = campaignQuery.data?.map(campaign => ({ id: campaign.id, title: campaign.title, raised: `Rp ${Number(campaign.raisedAmount ?? 0).toLocaleString("id-ID")}`, target: `Rp ${campaign.targetAmount.toLocaleString("id-ID")}`, progress: campaign.targetAmount > 0 ? Math.min(100, Math.round((Number(campaign.raisedAmount ?? 0) / campaign.targetAmount) * 100)) : 0, donors: Number(campaign.verifiedDonors ?? 0), used: `Rp ${Number(campaign.usedAmount ?? 0).toLocaleString("id-ID")}`, status: "Aktif" })) ?? []; const createCampaign = trpc.campaigns.create.useMutation({ onSuccess: campaign => { setCreatedCampaign(campaign ? { id: campaign.id, title: campaign.title, status: campaign.status } : null); setCampaignTitle(""); setCampaignSlug(""); setCampaignDescription(""); setCampaignTarget(""); toast.success("Draft kampanye tersimpan"); }, onError: error => toast.error(error.message || "Kampanye gagal disimpan") }); const publishCampaign = trpc.campaigns.publish.useMutation({ onSuccess: () => { setCreatedCampaign(null); campaignQuery.refetch(); draftQuery.refetch(); toast.success("Kampanye diterbitkan"); }, onError: error => toast.error(error.message || "Kampanye gagal diterbitkan") }); const saveCampaign = () => { if (!organizationId || !campaignTitle.trim() || !campaignSlug.trim() || !campaignTarget) return; createCampaign.mutate({ organizationId, title: campaignTitle.trim(), slug: campaignSlug.trim().toLowerCase(), description: campaignDescription.trim() || undefined, targetAmount: Number(campaignTarget) }); }; return <>{canManageCampaigns && <Card className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Buat kampanye donasi</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Draft baru hanya dapat dibuat dan diterbitkan oleh pengurus wilayah.</p></CardHeader><CardContent className="grid gap-2 px-5 pb-5 sm:grid-cols-2 sm:px-6"><Input value={campaignTitle} onChange={event => setCampaignTitle(event.target.value)} placeholder="Judul kampanye" className="h-9 rounded-lg border-[#dce8df] text-xs" /><Input value={campaignSlug} onChange={event => setCampaignSlug(event.target.value)} placeholder="slug-kampanye" className="h-9 rounded-lg border-[#dce8df] text-xs" /><Input value={campaignTarget} onChange={event => setCampaignTarget(event.target.value)} type="number" min="0" placeholder="Target nominal" className="h-9 rounded-lg border-[#dce8df] text-xs" /><Textarea value={campaignDescription} onChange={event => setCampaignDescription(event.target.value)} placeholder="Tujuan kampanye (opsional)" className="min-h-9 resize-none border-[#dce8df] text-xs" /><div className="flex flex-wrap items-center gap-2 sm:col-span-2"><Button onClick={saveCampaign} disabled={!organizationId || !campaignTitle.trim() || !campaignSlug.trim() || !campaignTarget || createCampaign.isPending} className="h-9 rounded-lg bg-[#173b33] text-xs font-bold text-white">{createCampaign.isPending ? "Menyimpan..." : "Simpan draft"}</Button>{createdCampaign && <><span className="text-xs text-[#6d8278]">Draft: {createdCampaign.title}</span><Button onClick={() => organizationId && publishCampaign.mutate({ organizationId, campaignId: createdCampaign.id })} disabled={publishCampaign.isPending} variant="outline" className="h-9 rounded-lg border-[#dce8df] text-xs font-bold text-[#4e7465]">{publishCampaign.isPending ? "Menerbitkan..." : "Terbitkan draft"}</Button></>}</div></CardContent></Card>}<div className="grid gap-4 md:grid-cols-3"><MiniStat label="Kampanye aktif" value={campaignQuery.data ? campaignQuery.data.length.toLocaleString("id-ID") : "—"} note="Wilayah aktif" icon={WalletCards} /><MiniStat label="Kontribusi" value={campaignQuery.data ? `Rp ${campaignQuery.data.reduce((sum, campaign) => sum + Number(campaign.raisedAmount ?? 0), 0).toLocaleString("id-ID")}` : "—"} note="Total kampanye aktif" icon={UsersRound} /><MiniStat label="Pembaruan dana" value={campaignQuery.data ? `Rp ${campaignQuery.data.reduce((sum, campaign) => sum + Number(campaign.usedAmount ?? 0), 0).toLocaleString("id-ID")}` : "—"} note="Penggunaan tercatat" icon={FileCheck2} /></div><div className="grid gap-5 md:grid-cols-2">{campaignQuery.isLoading ? <div className="rounded-2xl border border-[#e0e9e2] bg-white p-6 text-sm text-[#8a9b92]">Memuat kampanye...</div> : campaignQuery.isError ? <div className="flex items-center justify-between gap-3 rounded-2xl border border-[#f0d7cf] bg-[#fff8f5] p-6 text-sm text-[#9b5c49]"><span>Kampanye belum dapat dimuat.</span><Button variant="outline" onClick={() => campaignQuery.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : visibleCampaigns.length === 0 ? <div className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-6 text-center md:col-span-2"><p className="text-sm font-semibold text-[#35574c]">Belum ada kampanye aktif</p><p className="mt-1 text-xs text-[#8a9b92]">Kampanye yang dipublikasikan di wilayah aktif akan tampil di sini.</p></div> : visibleCampaigns.map(campaign => <Card key={campaign.id} className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><div className="flex items-start justify-between gap-3"><div><Badge className="rounded-full bg-[#e8f3ec] text-[10px] font-bold text-[#438367] hover:bg-[#e8f3ec]">{campaign.status}</Badge><CardTitle className="mt-3 text-xl tracking-[-0.04em] text-[#23483d]">{campaign.title}</CardTitle></div>{canReviewDonations ? <Button variant="ghost" onClick={() => setReviewCampaignId(campaign.id)} className="h-8 w-8 rounded-lg p-0 text-[#4b8068] hover:text-[#2d6049]"><ChevronRight className="h-4 w-4" /></Button> : <Button variant="ghost" className="h-8 w-8 rounded-lg p-0 text-[#a2b0a8]"><ChevronRight className="h-4 w-4" /></Button>}</div></CardHeader><CardContent className="px-5 pb-5 sm:px-6 sm:pb-6"><div className="flex items-end justify-between"><div><p className="text-2xl font-semibold tracking-[-0.05em] text-[#23483d]">{campaign.raised}</p><p className="mt-1 text-xs text-[#8a9b92]">dari target {campaign.target}</p></div><span className="text-sm font-bold text-[#a87027]">{campaign.progress}%</span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-[#e9f0eb]"><div className="h-full rounded-full bg-[#c9953c]" style={{ width: `${campaign.progress}%` }} /></div><div className="mt-4 flex items-center justify-between text-xs text-[#789087]"><span>{campaign.donors} donatur terverifikasi</span><span className="font-bold text-[#4b8068]">Lihat laporan</span></div>{campaign.id && <div className="mt-4 flex gap-2"><Input value={selectedCampaign === campaign.id ? amount : ""} onChange={event => { setSelectedCampaign(campaign.id ?? ""); setAmount(event.target.value); }} type="number" min="1" placeholder="Nominal kontribusi" className="h-9 rounded-lg border-[#dce8df] text-xs" /><Button disabled={selectedCampaign !== campaign.id || !amount || contribute.isPending} onClick={() => contribute.mutate({ campaignId: campaign.id ?? "", amount: Number(amount), visibility: "named" })} className="h-9 rounded-lg bg-[#173b33] px-3 text-xs font-bold text-white">Donasi</Button></div>}</CardContent></Card>)}</div>{canReviewDonations && reviewCampaignId && <><CampaignReviewPanel organizationId={organizationId} campaignId={reviewCampaignId} onChanged={campaignQuery.refetch} onBack={() => setReviewCampaignId(null)} />{canManageCampaigns && <Card className="mt-5 rounded-[24px] border-[#e0e9e2] bg-[#eef5ef] shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#9a6e2e]">Akuntabilitas</p><CardTitle className="mt-2 text-xl tracking-[-0.04em] text-[#23483d]">Catat penggunaan dana</CardTitle></CardHeader><CardContent className="grid gap-2 px-5 pb-5 sm:grid-cols-3 sm:px-6 sm:pb-6"><Input value={campaignQuery.data?.find(c => c.id === reviewCampaignId)?.title ?? ""} disabled className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Input value={usageAmount} onChange={event => setUsageAmount(event.target.value)} type="number" min="1" placeholder="Nominal" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs" /><Input value={usageDescription} onChange={event => setUsageDescription(event.target.value)} placeholder="Keterangan penggunaan" className="h-9 rounded-lg border-[#dce8df] bg-white text-xs sm:col-span-3" /><div className="flex flex-col gap-2 sm:col-span-3"><label className="text-[11px] font-semibold text-[#60786d]">Bukti penggunaan dana (opsional)</label><input type="file" accept="image/jpeg,image/png,application/pdf" onChange={chooseEvidence} disabled={!organizationId || uploadEvidence.isPending} className="h-9 rounded-lg border border-[#dce8df] bg-white px-3 py-1.5 text-xs text-[#60786d]" /><select value={usageEvidenceFileId} onChange={event => setUsageEvidenceFileId(event.target.value)} className="h-9 rounded-lg border border-[#dce8df] bg-white px-3 text-xs text-[#60786d]"><option value="">Pilih bukti private yang sudah tersimpan</option>{filesQuery.data?.map(file => <option key={file.id} value={file.id}>{file.filename}</option>)}</select>{filesQuery.isLoading && <p className="text-[11px] text-[#8a9b92]">Memuat bukti tersimpan...</p>}{filesQuery.isError && <p className="text-[11px] text-[#9b5c49]">Bukti tersimpan belum dapat dimuat.</p>}{!filesQuery.isLoading && !filesQuery.isError && !filesQuery.data?.length && <p className="text-[11px] text-[#8a9b92]">Belum ada bukti private. Unggah file di atas bila diperlukan.</p>}</div><Button onClick={() => { if (!organizationId || !reviewCampaignId || !usageAmount || !usageDescription.trim()) return; addFundUsage.mutate({ organizationId, campaignId: reviewCampaignId, amount: Number(usageAmount), description: usageDescription.trim(), evidenceFileId: usageEvidenceFileId || undefined }); }} disabled={!organizationId || !reviewCampaignId || !usageAmount || !usageDescription.trim() || filesQuery.isLoading || addFundUsage.isPending} className="h-9 rounded-lg bg-[#173b33] text-xs font-bold text-white sm:col-span-3">{addFundUsage.isPending ? "Menyimpan..." : "Simpan penggunaan dana"}</Button></CardContent></Card>}</>}<>{!reviewCampaignId && canManageCampaigns && <CampaignDraftsPanel organizationId={organizationId} canPublish={canManageCampaigns} onPublished={campaignQuery.refetch} />}</>;</> }

function CampaignDraftsPanel({ organizationId, canPublish, onPublished }: { organizationId?: string; canPublish: boolean; onPublished: () => void }) { const drafts = trpc.campaigns.drafts.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId) }); const publish = trpc.campaigns.publish.useMutation({ onSuccess: () => { drafts.refetch(); onPublished(); toast.success("Kampanye diterbitkan"); }, onError: error => toast.error(error.message || "Kampanye gagal diterbitkan") }); return <Card className="mt-5 rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6"><CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Draft kampanye</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Kampanye tersimpan sebagai draft dapat diterbitkan oleh pengurus.</p></CardHeader><CardContent className="space-y-2 px-5 pb-5 sm:px-6">{drafts.isLoading ? <p className="text-sm text-[#8a9b92]">Memuat draft kampanye...</p> : drafts.isError ? <p className="text-sm text-[#9b5c49]">Draft kampanye belum dapat dimuat.</p> : drafts.data?.length ? drafts.data.map(draft => <div key={draft.id} className="flex flex-col gap-3 rounded-2xl border border-[#e7eee9] p-4 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#35574c]">{draft.title}</p><p className="mt-1 text-xs text-[#8a9b92]">Target Rp {draft.targetAmount.toLocaleString("id-ID")} · Draft</p></div>{canPublish && <Button onClick={() => organizationId && publish.mutate({ organizationId, campaignId: draft.id })} disabled={publish.isPending} variant="outline" className="h-8 rounded-lg border-[#dce8df] px-3 text-[10px] font-bold text-[#4e7465]">{publish.isPending ? "Menerbitkan..." : "Terbitkan"}</Button>}</div>) : <p className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-5 text-center text-sm text-[#8a9b92]">Belum ada draft kampanye.</p>}</CardContent></Card>; }

function CampaignReviewPanel({ organizationId, campaignId, onChanged, onBack }: { organizationId?: string; campaignId?: string; onChanged: () => void; onBack?: () => void }) { const pending = trpc.campaigns.pending.useQuery({ organizationId: organizationId ?? "pending", campaignId }, { enabled: Boolean(organizationId) }); const verify = trpc.campaigns.verifyDonation.useMutation({ onSuccess: () => { pending.refetch(); onChanged(); toast.success("Status kontribusi diperbarui"); }, onError: error => toast.error(error.message || "Status kontribusi gagal diperbarui") }); return <Card className="mt-5 rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardHeader className="flex flex-row items-center justify-between space-y-0 px-5 pb-3 pt-5 sm:px-6"><div>{onBack && <button onClick={onBack} className="mb-2 flex items-center gap-1 text-[11px] font-bold text-[#4b8068] hover:text-[#2d6049]">← Kembali</button>}<CardTitle className="text-lg tracking-[-0.03em] text-[#23483d]">Verifikasi kontribusi</CardTitle><p className="mt-1 text-xs text-[#8a9b92]">Hanya pengurus keuangan yang dapat mengubah status.</p></div></CardHeader><CardContent className="space-y-2 px-5 pb-5 sm:px-6">{pending.isLoading ? <p className="text-sm text-[#8a9b92]">Memuat kontribusi pending...</p> : pending.isError ? <p className="text-sm text-[#9b5c49]">Kontribusi belum dapat dimuat.</p> : pending.data?.length ? pending.data.map(item => <div key={item.donation.id} className="flex flex-col gap-3 rounded-2xl border border-[#e7eee9] p-4 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#35574c]">{item.campaign.title}</p><p className="mt-1 text-xs text-[#8a9b92]">{item.donor.name ?? item.donor.email ?? "Warga"} · Rp {item.donation.amount.toLocaleString("id-ID")} · {campaignReviewLabel(item.donation.status)}</p></div><div className="flex gap-2"><Button onClick={() => organizationId && verify.mutate({ organizationId, ...campaignReviewAction(item.donation.id, "rejected") })} disabled={verify.isPending} variant="outline" className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[10px] font-bold text-[#9b5c49]">Tolak</Button><Button onClick={() => organizationId && verify.mutate({ organizationId, ...campaignReviewAction(item.donation.id, "verified") })} disabled={verify.isPending} className="h-8 rounded-lg bg-[#173b33] px-3 text-[10px] font-bold text-white">Verifikasi</Button></div></div>) : <p className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-5 text-center text-sm text-[#8a9b92]">Tidak ada kontribusi yang menunggu verifikasi.</p>}</CardContent></Card>; }

function ForumView({ organizationId, canCreateDiscussions = false }: { organizationId?: string; canCreateDiscussions?: boolean }) { useForumRealtime(organizationId); const [body, setBody] = useState(""); const [title, setTitle] = useState(""); const [scopeType, setScopeType] = useState<"general" | "event" | "announcement" | "campaign">("general"); const [scopeId, setScopeId] = useState(""); const [activeTopicId, setActiveTopicId] = useState<string | null>(null); const topicQuery = trpc.forum.listTopics.useQuery({ organizationId: organizationId ?? "pending", limit: 20, offset: 0 }, { enabled: Boolean(organizationId) }); const eventQuery = trpc.events.list.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId) && scopeType === "event" }); const announcementQuery = trpc.announcements.list.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId) && scopeType === "announcement" }); const campaignQuery = trpc.campaigns.list.useQuery({ organizationId: organizationId ?? "pending" }, { enabled: Boolean(organizationId) && scopeType === "campaign" }); const createTopic = trpc.forum.createTopic.useMutation({ onSuccess: () => { topicQuery.refetch(); toast.success("Topik diskusi tersimpan"); }, onError: error => toast.error(error.message || "Topik gagal dibuat") }); const createPost = trpc.forum.createPost.useMutation({ onSuccess: () => { setTitle(""); setBody(""); setScopeType("general"); setScopeId(""); topicQuery.refetch(); toast.success("Diskusi dipublikasikan"); }, onError: error => toast.error(error.message || "Diskusi gagal dipublikasikan") }); const publish = async () => { if (!organizationId || !title.trim() || !body.trim()) return; const topic = await createTopic.mutateAsync(buildForumTopicInput({ organizationId, title, scopeType, scopeId })); if (topic) createPost.mutate({ topicId: topic.id, body: body.trim() }); }; const visibleTopics = topicQuery.data?.map(topic => ({ id: topic.id, title: topic.title, context: topic.scopeType === "general" ? "Diskusi warga" : `Terkait ${topic.scopeType}${topic.scopeId ? ` · ${topic.scopeId}` : ""}`, replies: null, time: new Date(topic.createdAt).toLocaleDateString("id-ID"), tag: topic.scopeType === "general" ? "Umum" : topic.scopeType })) ?? []; return <div className="grid gap-5 xl:grid-cols-[1fr_0.45fr]"><div className="space-y-4">{canCreateDiscussions && <Card className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardContent className="p-5 sm:p-6"><div className="flex gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#dceee3] text-sm font-bold text-[#34785e]">AR</div><div className="min-w-0 flex-1"><Input value={title} onChange={event => setTitle(event.target.value)} placeholder="Judul diskusi" className="mb-2 h-10 rounded-xl border-[#dce8df] text-sm" /><Textarea value={body} onChange={event => setBody(event.target.value)} placeholder="Bagikan ide atau kabar untuk warga..." className="min-h-20 resize-none rounded-xl border-[#dce8df] text-sm" /><div className="mt-2 flex gap-2"><select value={scopeType} onChange={event => { const nextScope = nextForumScope(event.target.value as typeof scopeType); setScopeType(nextScope.scopeType); setScopeId(nextScope.scopeId); }} className="h-8 rounded-lg border border-[#dce8df] bg-white px-2 text-[11px] text-[#60786d]"><option value="general">Diskusi umum</option><option value="event">Terkait acara</option><option value="announcement">Terkait pengumuman</option><option value="campaign">Terkait kampanye</option></select>{scopeType !== "general" && <select value={scopeId} onChange={event => setScopeId(event.target.value)} className="h-8 min-w-0 flex-1 rounded-lg border border-[#dce8df] bg-white px-2 text-[11px] text-[#60786d]"><option value="">Pilih konteks (opsional)</option>{scopeType === "event" && (eventQuery.isLoading ? <option value="">Memuat acara...</option> : eventQuery.isError ? <option value="">Acara gagal dimuat</option> : eventQuery.data?.length ? eventQuery.data.map(item => <option key={item.event.id} value={item.event.id}>{item.event.title}</option>) : <option value="">Belum ada acara</option>)}{scopeType === "announcement" && (announcementQuery.isLoading ? <option value="">Memuat pengumuman...</option> : announcementQuery.isError ? <option value="">Pengumuman gagal dimuat</option> : announcementQuery.data?.length ? announcementQuery.data.map(item => <option key={item.id} value={item.id}>{item.title}</option>) : <option value="">Belum ada pengumuman</option>)}{scopeType === "campaign" && (campaignQuery.isLoading ? <option value="">Memuat kampanye...</option> : campaignQuery.isError ? <option value="">Kampanye gagal dimuat</option> : campaignQuery.data?.length ? campaignQuery.data.map(item => <option key={item.id} value={item.id}>{item.title}</option>) : <option value="">Belum ada kampanye</option>)}</select>}</div><div className="mt-3 flex justify-end"><Button onClick={publish} disabled={!title.trim() || !body.trim() || !organizationId || createTopic.isPending || createPost.isPending} className="h-9 rounded-xl bg-[#173b33] px-4 text-xs font-bold text-white hover:bg-[#255649]">{createTopic.isPending || createPost.isPending ? "Menerbitkan..." : "Publikasikan"}</Button></div></div></div></CardContent></Card>}{topicQuery.isLoading ? <div className="rounded-2xl border border-[#e0e9e2] bg-white p-6 text-sm text-[#8a9b92]">Memuat diskusi...</div> : topicQuery.isError ? <div className="flex items-center justify-between gap-3 rounded-2xl border border-[#f0d7cf] bg-[#fff8f5] p-6 text-sm text-[#9b5c49]"><span>Diskusi belum dapat dimuat.</span><Button variant="outline" onClick={() => topicQuery.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : visibleTopics.length === 0 ? <div className="rounded-2xl border border-dashed border-[#dce8df] bg-[#f7fbf8] p-6 text-center text-sm text-[#8a9b92]">Belum ada diskusi di wilayah aktif.</div> : visibleTopics.map(topic => <Card key={topic.id} className="rounded-[24px] border-[#e0e9e2] bg-white shadow-sm"><CardContent className="p-5 sm:p-6"><div className="flex items-start gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#e9eef8] text-[#456da8]"><MessageCircle className="h-4 w-4" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold text-[#35574c]">{topic.title}</h3><Badge variant="outline" className="rounded-full border-[#dce8df] text-[9px] text-[#638176]">{topic.tag}</Badge></div><p className="mt-2 text-xs text-[#6d8278]">{topic.context}</p><div className="mt-4 flex items-center gap-4 text-[11px] text-[#91a199]"><span>{topic.replies === null ? "Balasan belum dimuat" : `${topic.replies} balasan`}</span><span>{topic.time}</span><button onClick={() => setActiveTopicId(activeTopicId === topic.id ? null : topic.id)} className="font-bold text-[#4b8068] hover:text-[#2d6049]">Ikuti diskusi</button></div></div></div></CardContent></Card>)}</div>{(() => { const activeTopic = visibleTopics.find(item => item.id === activeTopicId); return activeTopic ? <ForumDiscussionPanel topicId={activeTopic.id} topicTitle={activeTopic.title} onClose={() => setActiveTopicId(null)} /> : null; })()}<Card className="h-fit rounded-[24px] border-[#e0e9e2] bg-[#173b33] text-white shadow-sm"><CardHeader className="px-5 pb-3 pt-5 sm:px-6 sm:pt-6"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#9ec1b2]">Panduan ruang</p><CardTitle className="mt-2 text-xl tracking-[-0.04em] text-white">Diskusi yang membangun</CardTitle></CardHeader><CardContent className="space-y-4 px-5 pb-5 sm:px-6 sm:pb-6"><p className="text-sm leading-6 text-[#c1d8cb]">Forum ini menjadi tempat bertukar kabar, bukan pengganti pengumuman resmi.</p>{["Gunakan judul yang jelas", "Hubungkan dengan kegiatan", "Jaga privasi sesama warga"].map((item, index) => <div key={item} className="flex items-center gap-3"><span className="flex h-6 w-6 items-center justify-center rounded-full bg-[#2c5c4e] text-[10px] font-bold text-[#f0c86f]">0{index + 1}</span><span className="text-xs font-semibold text-[#dfede5]">{item}</span></div>)}</CardContent></Card></div>; }

function ForumDiscussionPanel({ topicId, topicTitle, onClose }: { topicId: string; topicTitle: string; onClose: () => void }) { const [reply, setReply] = useState(""); const postsQuery = trpc.forum.listPosts.useQuery({ topicId }); const createPost = trpc.forum.createPost.useMutation({ onSuccess: () => { setReply(""); postsQuery.refetch(); toast.success("Balasan terkirim"); }, onError: error => toast.error(error.message || "Balasan gagal dikirim") }); const posts = postsQuery.data ?? []; return <Card className="rounded-[24px] border-[#dce8df] bg-[#f7fbf8] shadow-sm"><CardContent className="p-5 sm:p-6"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="text-xs font-bold uppercase tracking-[0.12em] text-[#638176]">Ikuti diskusi</p><p className="mt-1 truncate text-sm font-semibold text-[#35574c]">{topicTitle}</p></div><button onClick={onClose} className="text-[#9aaba2] hover:text-[#60786d]" aria-label="Tutup diskusi"><X className="h-4 w-4" /></button></div>{postsQuery.isLoading ? <p className="mt-3 text-sm text-[#8a9b92]">Memuat balasan...</p> : postsQuery.isError ? <div className="mt-3 flex items-center justify-between gap-3"><p className="text-sm text-[#9b5c49]">Balasan belum dapat dimuat.</p><Button variant="outline" onClick={() => postsQuery.refetch()} className="h-8 rounded-lg border-[#f0d7cf] px-3 text-[11px] font-bold text-[#9b5c49]">Coba lagi</Button></div> : posts.length === 0 ? <p className="mt-3 text-sm text-[#8a9b92]">Belum ada balasan. Jadilah yang pertama menjawab.</p> : <div className="mt-3 max-h-72 space-y-2 overflow-y-auto pr-1">{posts.map(({ post, author }) => <div key={post.id} className="flex gap-2"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#e9eef8] text-[9px] font-bold text-[#456da8]">{(author.name ?? "U").split(" ").map(part => part[0]).join("").slice(0, 2)}</div><div className="min-w-0 flex-1 rounded-xl border border-[#edf2ee] bg-white px-3 py-2"><p className="text-[10px] font-bold text-[#35574c]">{author.name ?? "Warga"}</p><p className="mt-0.5 whitespace-pre-wrap text-xs leading-5 text-[#6d8278]">{post.body}</p></div></div>)}</div>}<div className="mt-4 flex gap-2"><Textarea value={reply} onChange={event => setReply(event.target.value)} placeholder="Tulis balasan Anda..." className="min-h-16 flex-1 resize-none rounded-xl border-[#dce8df] text-xs" /><Button onClick={() => createPost.mutate({ topicId, body: reply.trim() })} disabled={!reply.trim() || createPost.isPending} className="h-9 self-end rounded-lg bg-[#173b33] px-4 text-xs font-bold text-white">{createPost.isPending ? "Mengirim..." : "Kirim balasan"}</Button></div></CardContent></Card>; }

function MiniStat({ label, value, note, icon: Icon }: { label: string; value: string; note: string; icon: typeof UsersRound }) { return <Card className="rounded-[22px] border-[#e0e9e2] bg-white shadow-sm"><CardContent className="flex items-start justify-between p-5"><div><p className="text-xs font-medium text-[#80948a]">{label}</p><p className="mt-3 text-2xl font-semibold tracking-[-0.05em] text-[#23483d]">{value}</p><p className="mt-1 text-[11px] font-semibold text-[#6b927e]">{note}</p></div><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e7f2eb] text-[#34785e]"><Icon className="h-4 w-4" /></div></CardContent></Card>; }
